  '\\nfrom the name\\n' => '\\ndel nombre\\n',
  '\\nRemove option\\n' => '\\nEliminar opción\\n',
  'Unit' => 'Unidad',
  '\\n— note set\\n' => '\\n— conjunto de notas\\n',
