  '\\nMapping for “%s”\\n' => '\\nAsignación de “%s”\\n',
  '\\nThis form charges in%1$sbut the donation type is in%2$s: its payments are stopped until both use the same currency.\\n' => '\\nEste formulario se cobra en%1$spero el tipo de donación está en%2$s: sus pagos se detienen hasta que ambos utilicen la misma moneda.\\n',
  '\\nThis form has no priced choices to map.\\n' => '\\nEste formulario no tiene opciones de precios para asignar.\\n',
  '\\nForm choice\\n' => '\\nElección de formulario\\n',
