  '\\nProxy consent field\\n' => '\\nCampo de consentimiento de proxy\\n',
  '\\nMonthly, weekly or yearly gifts charged automatically by the payment provider.\\n' => '\\nRegalos mensuales, semanales o anuales cobrados automáticamente por el proveedor de pagos.\\n',
  '\\nName, e-mail, phone, reference...\\n' => '\\nNombre, email, teléfono, referencia...\\n',
