  '[[\'%srecurring donation\', \'en\']]' . chr(0) . '[[\'%srecurring donations\', \'en\']]' => '[[\'%sdonación recurrente\', \'es\']]' . chr(0) . '[[\'%sdonaciones recurrentes\', \'es\']]',
