  '\\nCard payment could not start:%1$s(card%2$s,%3$s).\\n' => '\\nNo se pudo iniciar el pago con tarjeta:%1$s(tarjeta%2$s,%3$s).\\n',
  '\\ntest mode\\n' => '\\modo de prueba\\n',
  '\\nlive\\n' => '\\nen vivo\\n',
  '\\nCard payment started:%1$sinstallments,%2$scharged by the bank.\\n' => '\\nPago con tarjeta iniciado:%1$scuotas,%2$scobrado por el banco.\\n',
  '\\niyzico 3D Secure:%s\\n' => '\\niyzico 3D Seguro:%s\\n',
