  '\\nThe bank could not check the card. Please try again or use another card.\\n' => '\\nEl banco no pudo comprobar la tarjeta. Inténtalo de nuevo o utiliza otra tarjeta.\\n',
  '\\niyzico: the payment was not completed (%s).\\n' => '\\niyzico: el pago no se completó (%s).\\n',
  '[[\'Default address\\n' => '[[\'Dirección predeterminada\\n',
