  '\\nKeys are read from Donations › Settings › Payments › iyzico.\\n' => '\\nLas claves se leen desde Donaciones › Configuración › Pagos › iyzico.\\n',
  '\\nNo iyzico keys found. Enter them in the iyzico WooCommerce plugin or in Donations › Settings › Payments › iyzico.\\n' => '\\nNo se encontraron claves iyzico. Introdúcelos en el complemento WooCommerce de iyzico o en Donaciones › Configuración › Pagos › iyzico.\\n',
  '\\nEnvironment: sandbox (test).\\n' => '\\nEntorno: sandbox (prueba).\\n',
  '\\nEnvironment: live.\\n' => '\\nEntorno: en vivo.\\n',
  '\\niyzico reported a payment (%s) that does not match this order (amount, currency or basket). Check it in the iyzico panel before doing anything.\\n' => '\\niyzico informó un pago (%s) que no coincide con este pedido (monto, moneda o cesta). Compruébalo en el panel de iyzico antes de hacer cualquier cosa.\\n',
  '\\niyzico payment received:%1$s, payment id%2$s(%3$s).\\n' => '\\niyzico pago recibido:%1$s, ID de pago%2$s(%3$s).\\n',
