  '\\nHeading over the options\\n' => '\\nRevisando las opciones\\n',
  '\\nChoose an option\\n' => '\\nElige una opción\\n',
  '\\nHow the options are shown\\n' => '\\nCómo se muestran las opciones\\n',
  '\\nOrder of the sections\\n' => '\\nOrden de las secciones\\n',
