  '\\nTicked by default\\n' => '\\nMarcado de forma predeterminada\\n',
  '\\nFixed\\n' => '\\nFijo\\n',
  '\\nEmpty or 0 = no fee for that method (for example bank transfer). Fee = donation × % + fixed.\\n' => '\\nVacío o 0 = sin cargo por ese método (por ejemplo, transferencia bancaria). Tarifa = donación × % + fijo.\\n',
  '\\nPlease choose what you would like to donate for.\\n' => '\\nPor favor, elija para qué le gustaría donar.\\n',
