  '\\nThe amount must be at least%s.\\n' => '\\nEl monto debe ser al menos%s.\\n',
  '\\nFor this amount please get in touch with us.\\n' => '\\nPara este importe por favor póngase en contacto con nosotros.\\n',
  '\\nPlease choose an option.\\n' => '\\nPor favor elija una opción.\\n',
