  '\\nPlease write the postal address for the printed certificate.\\n' => '\\nPor favor escriba la dirección postal del certificado impreso.\\n',
  '\\nPlease write the name of the person you are donating for.\\n' => '\\nPor favor escriba el nombre de la persona para la que está donando.\\n',
  '\\nThis donation needs a proxy (vekâlet) consent, but it is not set up yet. Please contact the site administrator.\\n' => '\\nEsta donación necesita un consentimiento de proxy (vekâlet), pero aún no está configurado. Comuníquese con el administrador del sitio.\\n',
  '\\nThe proxy (vekâlet) text has been updated. Please read it again and accept it.\\n' => '\\nEl texto del proxy (vekâlet) ha sido actualizado. Por favor léelo de nuevo y acéptalo.\\n',
  '[[\'Please write at most%sname (one per share).\', \'en\']]' . chr(0) . '[[\'Please write at most%snames (one per share).\', \'en\']]' => '[[\'Por favor escriba como máximo el nombre%s(uno por recurso compartido).\', \'es\']]' . chr(0) . '[[\'Por favor escriba como máximo nombres%s(uno por recurso compartido).\', \'es\']]',
  '\\nThe phone number does not look right. Example: 0532 123 45 67\\n' => '\\nEl número de teléfono no parece correcto. Ejemplo: 0532 123 45 67\\n',
  '\\nThe e-mail address does not look right.\\n' => '\\nLa dirección de correo electrónico no parece correcta.\\n',
