  '\\nProducts in your cart can only be paid in%1$s.<a href="%2$s">Switch to%1$s</a>\\n' => '\\nLos productos en su carrito solo se pueden pagar en%1$s.<a href="%2$s">Cambiar a%1$s</a>\\n',
