  '\\nThe certificate could not be made: no Flux Certificates template was found (Donations › Settings › WooCommerce).\\n' => '\\nNo se pudo crear el certificado: no se encontró ninguna plantilla de Certificados Flux (Donaciones › Configuración › WooCommerce).\\n',
  '\\nThe certificate could not be made:%s\\n' => '\\nNo se pudo crear el certificado:%s\\n',
