  '\\nCertificate made:%1$s(%2$s).%3$s\\n' => '\\nCertificado realizado:%1$s(%2$s).%3$s\\n',
  '\\nCertificates made again (%d); the old ones were revoked.\\n' => '\\nCertificados realizados nuevamente (%d); los antiguos fueron revocados.\\n',
  '\\nNo delivery channel is chosen.\\n' => '\\nNo se ha elegido ningún canal de entrega.\\n',
  '\\nQueued:%s.\\n' => '\\nEn cola:%s.\\n',
  '\\nCopy to the donor:%s.\\n' => '\\nCopia al donante:%s.\\n',
  'Link copied' => 'Enlace copiado',
  '\\nThe preview could not be drawn. You can open it with "View certificate".\\n' => '\\nNo se pudo dibujar la vista previa. Puedes abrirlo con "Ver certificado".\\n',
  '[[\'Your certificate is ready\', \'en\']]' . chr(0) . '[[\'Your certificates are ready\', \'en\']]' => '[[\'Tu certificado está listo\', \'es\']]' . chr(0) . '[[\'Tus certificados están listos\', \'es\']]',
  '\\nNo:%s\\n' => '\\nNo:%s\\n',
  'Download PDF' => 'Descargar PDF',
  '\\nView certificate\\n' => '\\nVer certificado\\n',
  '\\nYour certificate is being prepared. It will be sent by WhatsApp and e-mail in a few minutes; you can also refresh this page to see it.\\n' => '\\nSu certificado se está preparando. Se enviará por WhatsApp y correo electrónico en unos minutos; También puedes actualizar esta página para verla.\\n',
  '\\nThis certificate design cannot be chosen any more. Please pick another one.\\n' => '\\nEste diseño de certificado ya no se puede elegir. Elige otro.\\n',
  '\\nPlease fill in "%s" for the certificate.\\n' => '\\nPor favor complete "%s" para el certificado.\\n',
  '\\nPick the design of your certificate. The donation amount does not change.\\n' => '\\nElija el diseño de su certificado. El monto de la donación no cambia.\\n',
  'Standard' => 'Estándar',
  '\\n"%s" was paid once: the card was not stored, so it will not repeat monthly.\\n' => '\\n"%s" se pagó una vez: la tarjeta no se almacenó, por lo que no se repetirá mensualmente.\\n',
  '\\n"%1$s" repeats monthly (recurring donation #%2$d); the card is stored at iyzico.\\n' => '\\n"%1$s" se repite mensualmente (donación recurrente #%2$d); la tarjeta se almacena en iyzico.\\n',
  '\\nCard (iyzico), monthly\\n' => '\\nTarjeta (iyzico), mensual\\n',
  '\\nMonthly renewal of recurring donation #%1$d(first order #%2$s).\\n' => '\\nRenovación mensual de la donación recurrente #%1$d(primer pedido #%2$s).\\n',
  '\\nMonthly charge accepted by iyzico:%1$s, payment id%2$s.\\n' => '\\nCargo mensual aceptado por iyzico:%1$s, ID de pago%2$s.\\n',
  '\\nMonthly charge failed after the last attempt:%s\\n' => '\\nEl cargo mensual falló después del último intento:%s\\n',
  '\\nMonthly charge failed, it will be retried:%s\\n' => '\\nEl cargo mensual falló, se volverá a intentar:%s\\n',
  '\\nFlux Donate always uses EsnekPOS\'s secure payment page; the bank asks for 3D Secure there when needed.\\n' => '\\nFlux Donate siempre utiliza la página de pago seguro de EsnekPOS; el banco solicita 3D Secure allí cuando es necesario.\\n',
  '\\nFlux Donate\\n' => '\\nFlux Donar\\n',
  '\\nFlux Donate runs this payment method: classic and block checkout, payment links without a cart, and every payment is confirmed with EsnekPOS from the server before the order is marked paid. For a test, enter merchant TEST1234 and the test merchant key from EsnekPOS\\\'s developer page.\\n' => '\\nFlux Donate ejecuta este método de pago: pago clásico y en bloque, enlaces de pago sin carrito, y cada pago se confirma con EsnekPOS desde el servidor antes de que el pedido se marque como pagado. Para una prueba, ingrese el comerciante TEST1234 y la clave de comerciante de prueba de la página de desarrollador de EsnekPOS.\\n',
  '\\nDonation #%d\\n' => '\\nDonación #%d\\n',
  '\\nEsnekPOS did not answer (HTTP%d).\\n' => '\\nEsnekPOS no respondió (HTTP%d).\\n',
  '\\nEsnekPOS payment could not start:%s\\n' => '\\nEl pago de EsnekPOS no pudo iniciarse:%s\\n',
  '\\nEsnekPOS payment could not start:%1$s(%2$s).\\n' => '\\nEl pago de EsnekPOS no pudo iniciarse:%1$s(%2$s).\\n',
  '\\nThe payment is being checked. Please wait a moment and refresh the page.\\n' => '\\nEl pago está siendo verificado. Espere un momento y actualice la página.\\n',
  '\\nEsnekPOS payment could not be checked:%s\\n' => '\\nNo se pudo verificar el pago de EsnekPOS:%s\\n',
  '\\nThe payment could not be verified yet. If money was taken from your card, please contact us before trying again.\\n' => '\\nEl pago aún no se ha podido verificar. Si se quitó dinero de tu tarjeta, contáctanos antes de volver a intentarlo.\\n',
  '\\nEsnekPOS payment received: reference%1$s,%2$sinstallment(s),%3$scharged.\\n' => '\\nPago de EsnekPOS recibido: referencia%1$s, cuota(s)%2$s,%3$scargado.\\n',
  '\\nEsnekPOS reported a payment (%s) that does not match this order (amount or reference). Check it in the EsnekPOS panel before doing anything.\\n' => '\\nEsnekPOS informó un pago (%s) que no coincide con este pedido (monto o referencia). Compruébalo en el panel de EsnekPOS antes de hacer nada.\\n',
  '\\nEsnekPOS return said success but EsnekPOS did not confirm the payment:%s\\n' => '\\nLa devolución de EsnekPOS dijo éxito pero EsnekPOS no confirmó el pago:%s\\n',
  '\\nEsnekPOS: the payment was not completed (%s).\\n' => '\\nEsnekPOS: el pago no se completó (%s).\\n',
  '\\nTest mode (merchant TEST1234).\\n' => '\\nModo de prueba (comerciante TEST1234).\\n',
  '\\nFlux Donate sends the order lines, no cart needed.\\n' => '\\nFlux Donate envía las líneas de pedido, no se necesita carrito.\\n',
  '\\nFlux Donate asks EsnekPOS (ProcessQuery) before the order is marked paid.\\n' => '\\nFlux Donate pregunta a EsnekPOS (ProcessQuery) antes de que el pedido se marque como pagado.\\n',
  '\\nOn EsnekPOS\\\'s payment page, as set in the EsnekPOS panel.\\n' => '\\nEn la página de pago de EsnekPOS, tal como se establece en el panel de EsnekPOS.\\n',
  '\\nRefund in the EsnekPOS panel, then mark the order refunded.\\n' => '\\nReembolsar en el panel de EsnekPOS, luego marcar el pedido como reembolsado.\\n',
  '[[\'Donation of%1$ssapling.%2$splants it for you and sends an online certificate in your name. Pay by card or bank transfer.\', \'en\']]' . chr(0) . '[[\'Donation of%1$ssaplings.%2$splants them for you and sends an online certificate in your name. Pay by card or bank transfer.\', \'en\']]' => '[[\'Donación de retoño%1$s.%2$slo planta por usted y envía un certificado en línea a su nombre. Paga con tarjeta o transferencia bancaria.\', \'es\']]' . chr(0) . '[[\'Donación de plantones%1$s.%2$slos planta por usted y envía un certificado en línea a su nombre. Paga con tarjeta o transferencia bancaria.\', \'es\']]',
  '\\nDonation packages\\n' => '\\nPaquetes de donación\\n',
  '\\nDonation >%s\\n' => '\\nDonación >%s\\n',
  '\\nI will also cover the transaction fee\\n' => '\\nTambién cubriré la tarifa de transacción\\n',
  '\\nSo your whole donation reaches its purpose. The exact fee depends on the payment method and is shown at the checkout.\\n' => '\\nAsí que toda tu donación alcanza su propósito. La tarifa exacta depende del método de pago y se muestra al finalizar la compra.\\n',
  '\\nTransaction fee (covered by you)\\n' => '\\nTarifa de transacción (cubierta por usted)\\n',
  '\\nAny trouble? Write to us on WhatsApp:\\n' => '\\n¿Algún problema? Escríbenos a WhatsApp:\\n',
  '\\nNo badge\\n' => '\\nSin insignia\\n',
  '\\nBest value\\n' => '\\nMejor valor\\n',
  '\\nMost popular\', \'en\']]' => '\\nMás popular\', \'es\']]',
  '\\nFamily pack\\n' => '\\nPaquete familiar\\n',
  '\\nHello{ad}, your donation of{tutar}is registered. IBAN:{iban}Reference:{aciklama}Upload your receipt:{link}\\n' => '\\nHola{ad}, tu donación de{tutar}está registrada. IBAN:{iban}Referencia:{aciklama}Sube tu recibo:{link}\\n',
  '\\nHello{ad}🌱\\n\\nYour donation of *{tutar}* is registered (No:{siparis}).\\n\\nBank transfer details:\\nRecipient:{alici}\\nIBAN:{iban}\\nReference: *{aciklama}*\\n\\nAfter the transfer you can upload your receipt here:\\n{link}\\n\\nThank you,\\n{site}\\n' => '\\nHola{ad}🌱\\n\\nTu donación de *{tutar}* está registrada (No:{siparis}).\\n\\nDetalles de la transferencia bancaria:\\nDestinatario:{alici}\\nIBAN:{iban}\\nReferencia: *{aciklama}*\\n\\nDespués de la transferencia puedes cargar tu recibo aquí:\\n{link}\\n\\nGracias,\\n{site}\\n',
  '\\nPending transfer notification sent:%s.\\n' => '\\nNotificación de transferencia pendiente enviada:%s.\\n',
  '\\nWooCommerce checks\\n' => '\\nComprobaciones de WooCommerce\\n',
  'This check could not run: %s' => 'Esta verificación no se pudo ejecutar:%s',
  '\\nVersion%1$sis active. Flux Donate was checked up to%2$s; it uses only stable public WooCommerce functions, but test a donation after big WooCommerce updates.\\n' => '\\nLa versión%1$sestá activa. Flux Donate se comprobó en%2$s; solo utiliza funciones públicas estables de WooCommerce, pero prueba una donación después de grandes actualizaciones de WooCommerce.\\n',
  '\\nActive, version%s. Donations are paid through the WooCommerce cart and checkout.\\n' => '\\nActivo, versión%s. Las donaciones se pagan a través del carrito de WooCommerce y al finalizar la compra.\\n',
  '\\nOne-time card payments are taken by%s; iyzico is not shown at the checkout.\\n' => '\\nLos pagos únicos con tarjeta se realizan mediante%s; iyzico no se muestra en la caja.\\n',
  '\\nOne-time card payments are taken by the official iyzico WooCommerce plugin.\\n' => '\\nLos pagos únicos con tarjeta se realizan mediante el complemento oficial de iyzico WooCommerce.\\n',
  '\\nCard payments use our own card fields on the checkout (iyzico 3D Secure, installments, saved cards).\\n' => '\\nLos pagos con tarjeta utilizan nuestros propios campos de tarjeta en la caja (iyzico 3D Secure, cuotas, tarjetas guardadas).\\n',
  '\\nOne-time card payments are taken by Flux Donate iyzico (the official iyzico plugin is not enabled).\\n' => '\\nLos pagos únicos con tarjeta los realiza Flux Donate iyzico (el complemento oficial de iyzico no está habilitado).\\n',
  '\\nCard payments are taken by:%s.\\n' => '\\nLos pagos con tarjeta se realizan mediante:%s.\\n',
  '\\nNo card method is enabled; donations can only be paid by bank transfer.\\n' => '\\nNo hay ningún método de tarjeta habilitado; las donaciones sólo se pueden pagar mediante transferencia bancaria.\\n',
  '\\nCard payments (WooCommerce)\\n' => '\\nPagos con tarjeta (WooCommerce)\\n',
  '\\nMonthly donations\\n' => '\\nDonaciones mensuales\\n',
  '\\nFlux Donate iyzico stores the card at the first payment; a renewal order is opened and charged every month.\\n' => '\\nFlux Donate iyzico almacena la tarjeta en el primer pago; se abre y cobra una orden de renovación cada mes.\\n',
  '\\nMonthly donations are off: enable "Card (iyzico) - Flux Donate" in WooCommerce › Settings › Payments and enter iyzico keys.\\n' => '\\nLas donaciones mensuales están desactivadas: habilite "Tarjeta (iyzico) - Flux Donate" en WooCommerce › Configuración › Pagos e ingrese las claves de iyzico.\\n',
  '\\nBank transfer (donations)\\n' => '\\nTransferencia bancaria (donaciones)\\n',
  '\\nNo IBAN entered.\\n' => '\\nNo se ha introducido ningún IBAN.\\n',
  '\\nThe payment method is disabled.\\n' => '\\nEl método de pago está deshabilitado.\\n',
  '\\nBank transfer settings\\n' => '\\nConfiguración de transferencia bancaria\\n',
  '\\nTwo bank transfer methods\\n' => '\\nDos métodos de transferencia bancaria\\n',
  '\\nWooCommerce\\\'s own "Direct bank transfer" is enabled next to the donation bank transfer. Donors see two similar choices and the receipt upload works only with the donation one; disable "Direct bank transfer".\\n' => '\\nLa "Transferencia bancaria directa" propia de WooCommerce está habilitada junto a la transferencia bancaria de donación. Los donantes ven dos opciones similares y la carga del recibo funciona solo con la de donación; deshabilitar "Transferencia bancaria directa".\\n',
  '\\nThe shop currency is%1$s; these types use another currency and are charged in%1$sat the same number:%2$s\\n' => '\\nLa moneda de la tienda es%1$s; estos tipos usan otra moneda y se cobran en%1$sal mismo número:%2$s\\n',
  '\\nWooCommerce settings\\n' => '\\nConfiguración de WooCommerce\\n',
  '\\nDonation types and the shop use%s.\\n' => '\\nLos tipos de donación y la tienda utilizan%s.\\n',
  '\\nDonation products\\n' => '\\nProductos de donación\\n',
  '\\nThese types get their hidden WooCommerce product the first time they are donated to or saved:%s\\n' => '\\nEstos tipos obtienen su producto WooCommerce oculto la primera vez que se donan o se guardan:%s\\n',
  '\\n%dactive type has its hidden WooCommerce product.%dactive types have their hidden WooCommerce products.\\n' => '\\n El tipo activo%dtiene su producto WooCommerce oculto.%dlos tipos activos tienen sus productos WooCommerce ocultos.\\n',
  '\\nNo page with the donation options block is selected.\\n' => '\\nNo se ha seleccionado ninguna página con el bloque de opciones de donación.\\n',
  '\\nOther payment plugins\\n' => '\\nOtros complementos de pago\\n',
  '\\nCheck these on the donation checkout:%s. Details: Donations › Settings › WooCommerce › Payment methods.\\n' => '\\nConsulte estos en el proceso de pago de donaciones:%s. Detalles: Donaciones › Configuración › WooCommerce › Métodos de pago.\\n',
  'Payment methods' => 'Métodos de pago',
  '\\nEnabled and shown on the donation checkout:%s.\\n' => '\\nHabilitado y mostrado en el pago de donaciones:%s.\\n',
  '\\nCertificates after payment\\n' => '\\nCertificados después del pago\\n',
  '\\nFlux Certificates makes the certificates of paid donation lines.\\n' => '\\nFlux Certificates fabrica los certificados de líneas de donación pagada.\\n',
  '\\nFlux Certificates has no active template.\\n' => '\\nCertificados Flux no tiene plantilla activa.\\n',
  '\\nProduct XML\\n' => '\\nXML del producto\\n',
  '\\n%1$slists%2$ddonation packages (Google Merchant format, e.g. for iyzico).\\n' => '\\n%1$senumera los paquetes de donación%2$d(formato de Google Merchant, por ejemplo, para iyzico).\\n',
  '\\nPayment forms on the checkout\\n' => '\\nFormularios de pago al finalizar la compra\\n',
  '\\nDonation forms send their choice to the WooCommerce cart; "Payment completed" automations run when the order is paid.\\n' => '\\nLos formularios de donación envían su elección al carrito de WooCommerce; Las automatizaciones de "Pago completado" se ejecutan cuando se paga el pedido.\\n',
  '\\nFlux Forms%sis active. Forms are paid on the checkout, but their "Payment completed" automations need Flux Forms 2.1.0 or later.\\n' => '\\nFlux Forms%sestá activo. Los formularios se pagan al finalizar la compra, pero sus automatizaciones de "Pago completado" necesitan Flux Forms 2.1.0 o posterior.\\n',
  'Plugins' => 'Complementos',
  '\\nDonation e-mails\\n' => '\\nCorreos electrónicos de donación\\n',
  '\\nSent by Flux Mail; the templates (group "Flux Donate") can be edited there. WooCommerce order e-mails stay in WooCommerce › Settings › Emails.\\n' => '\\nEnviado por correo Flux; Las plantillas (grupo "Flux Donate") se pueden editar allí. Los correos electrónicos de pedidos de WooCommerce permanecen en WooCommerce › Configuración › Correos electrónicos.\\n',
  '\\nE-mail templates\\n' => '\\nPlantillas de correo electrónico\\n',
  '\\nFlux Mail is not active: the donation e-mails are sent as plain text with their default wording.\\n' => '\\nFlux Mail no está activo: los correos electrónicos de donación se envían como texto sin formato con su redacción predeterminada.\\n',
  '\\nBank transfer (donation)\\n' => '\\nTransferencia bancaria (donación)\\n',
  '\\nThe donor transfers the money with an order-specific reference and uploads the receipt on the site. The certificate is issued when you confirm the payment.\\n' => '\\nEl donante transfiere el dinero con una referencia específica del pedido y carga el recibo en el sitio. El certificado se emite cuando confirmas el pago.\\n',
  'Enabled' => 'Habilitado',
  '\\nTake donations by bank transfer\\n' => '\\nAceptar donaciones mediante transferencia bancaria\\n',
  'Empty = "Bank transfer" in the site language.' => 'Vacío = "Transferencia bancaria" en el idioma del sitio.',
  'Text on the checkout page' => 'Texto en la página de pago',
  'Empty = the default text in the site language.' => 'Vacío = el texto predeterminado en el idioma del sitio.',
  'Recipient (account holder)' => 'Destinatario (titular de la cuenta)',
  '\\nEmpty = the holder of the bank account below or, without an IBAN here, of WooCommerce\\\'s "Direct bank transfer" account (else the theme settings).\\n' => '\\nVacío = el titular de la cuenta bancaria a continuación o, sin un IBAN aquí, de la cuenta de "Transferencia bancaria directa" de WooCommerce (de lo contrario, la configuración del tema).\\n',
  '\\nThe account shown everywhere (donation page, checkout, call center). Empty = the first account of WooCommerce\\\'s "Direct bank transfer", else the theme settings; recipient and bank then come from that account too.\\n' => '\\nLa cuenta se muestra en todas partes (página de donaciones, pago, centro de llamadas). Vacío = la primera cuenta de "Transferencia bancaria directa" de WooCommerce; de ​​lo contrario, la configuración del tema; El destinatario y el banco también provienen de esa cuenta.\\n',
  'Bank (optional)' => 'Banco (opcional)',
  '\\nWhat the donor writes in the transfer description. Placeholders:{tur}(sapling donation / donation),{kod}(prefix + order no),{siparis},{ad}. Empty:{tur}{kod}{ad}\\n' => '\\nLo que escribe el donante en la descripción de la transferencia. Marcadores de posición:{tur}(donación de retoño/donación),{kod}(prefijo + número de pedido),{siparis},{ad}. Vacío:{tur}{kod}{ad}\\n',
  'Code prefix' => 'Prefijo de código',
  '\\nBank transfer pre-registration: waiting for the payment.\\n' => '\\nPreinscripción por transferencia bancaria: esperando el pago.\\n',
  '\\nCard (iyzico) - Flux Donate\\n' => '\\nTarjeta (iyzico) - Donar Flux\\n',
  '\\nCard payments on iyzico\'s secure page. Required for monthly donations (the card is stored by iyzico and charged each month); also used for one-time donations when the official iyzico plugin is not active.\\n' => '\\nPagos con tarjeta en la página segura de iyzico. Requerido para donaciones mensuales (iyzico almacena la tarjeta y se carga cada mes); También se utiliza para donaciones únicas cuando el complemento oficial de iyzico no está activo.\\n',
  'Enable' => 'Habilitar',
  '\\nCard payments through Flux Donate (iyzico)\\n' => '\\nPagos con tarjeta a través de Flux Donate (iyzico)\\n',
  '\\nCredit / debit card (iyzico)\\n' => '\\nTarjeta de crédito/débito (iyzico)\\n',
  'Description' => 'Descripción',
  'API keys' => 'Claves API',
  '\\nYou will pay on iyzico\'s secure page. For monthly donations your card is stored by iyzico and charged once a month; you can cancel at any time.\\n' => '\\nPagarás en la página segura de iyzico. Para donaciones mensuales, iyzico almacena su tarjeta y la carga una vez al mes; puedes cancelar en cualquier momento.\\n',
  '\\nDonation options\\n' => '\\nOpciones de donación\\n',
  '\\nSapling packages, causes and free-amount donations; added to the cart and paid with WooCommerce.\\n' => '\\nPaquetes de retoños, causas y donaciones gratuitas; añadido al carrito y pagado con WooCommerce.\\n',
  '\\nTab shown first\\n' => '\\nLa pestaña se muestra primero\\n',
  '\\nThe first one\\n' => '\\nEl primero\\n',
  '\\nNone chosen = the types marked "Show in the Donation options block".\\n' => '\\nNinguno elegido = los tipos marcados "Mostrar en el bloque de opciones de donación".\\n',
  '\\nPrices and options: Donations › Donation types. Certificates and cart: Donations › Settings › WooCommerce.\\n' => '\\nPrecios y opciones: Donaciones › Tipos de donación. Certificados y carrito: Donaciones › Configuración › WooCommerce.\\n',
