  '\\nPay safely by card or bank transfer.\\n' => '\\nPague de forma segura con tarjeta o transferencia bancaria.\\n',
  '\\nYour card details are never stored on our site.\\n' => '\\nLos datos de su tarjeta nunca se almacenan en nuestro sitio.\\n',
