  '\\nSet in wp-config.php. Saved iyzico cards are encrypted with them: do not change them, or saved cards stop working.\\n' => '\\nEstablecer en wp-config.php. Las tarjetas iyzico guardadas se cifran con ellos: no las cambies o las tarjetas guardadas dejarán de funcionar.\\n',
  'Database tables' => 'tablas de base de datos',
  '\\nUp to date (%s).\\n' => '\\nActualizado (%s).\\n',
  '\\nTables are at version%1$s, expected%2$s. Deactivate and activate Flux Donate to update them.\\n' => '\\nLas tablas tienen la versión%1$s, se esperaba%2$s. Desactiva y activa Flux Donate para actualizarlos.\\n',
