  '\\nThis server could not reach its own wp-cron.php (%s). WP-Cron cannot start from visits; add a server cron job.\\n' => '\\nEste servidor no pudo acceder a su propio wp-cron.php (%s). WP-Cron no puede comenzar con visitas; agregue un trabajo cron del servidor.\\n',
  '\\nwp-cron.php answered; WP-Cron can start.\\n' => '\\nwp-cron.php respondió; WP-Cron puede iniciarse.\\n',
  '\\nwp-cron.php answered with HTTP%d(blocked by the host or a security plugin?). Add a server cron job.\\n' => '\\nwp-cron.php respondió con HTTP%d(¿bloqueado por el host o por un complemento de seguridad?). Agregue una tarea cron del servidor.\\n',
  '\\n[%s] Test e-mail from Flux Donate\\n' => '\\n[%s] Correo electrónico de prueba de Flux Donate\\n',
  '\\nThis is a test from Donations › Settings › System check. If you can read it, donor e-mails can be sent.\\n' => '\\nEsta es una prueba de Donaciones › Configuración › Verificación del sistema. Si puede leerlo, se pueden enviar correos electrónicos a los donantes.\\n',
  '\\nSent to%s. Check that it arrived (and not in spam).\\n' => '\\nEnviado a%s. Comprueba que haya llegado (y que no sea spam).\\n',
