  'Version %1$s · %2$s' => '\\nVersión%1$s·%2$s\\n',
  'Add your own tabs with fields to tracked records ("on": "item") or donations ("on": "donation"), for all or some donation types. Leave it empty if you do not need any.' => '\\nAgregue sus propias pestañas con campos a registros rastreados ("on": "item") o donaciones ("on": "donation"), para todos o algunos tipos de donaciones. Déjalo vacío si no necesitas ninguno.\\n',
  'Tabs (JSON list)' => '\\nPestañas (lista JSON)\\n',
  'Tabs in use' => '\\nPestañas en uso\\n',
  'Record page' => '\\nPágina de registro\\n',
