  'canceled %s' => '\\ncancelado%s\\n',
  'Cancel this recurring donation at the payment provider? No further charges will be made.' => '\\n¿Cancelar esta donación recurrente en el proveedor de pagos? No se realizarán más cargos.\\n',
  'Card payments: the official iyzico plugin is enabled.' => '\\nPagos con tarjeta: el complemento oficial de iyzico está habilitado.\\n',
